from funcy import decorator

@decorator
def my_deco(call, *, opt=True):
    result = call()
    if opt:
        return result * 2
    return result

@my_deco
def f(x):
    return x

print('R5 test:', f(5))

# Also test without kwonly to make sure we didn't break existing behavior
